const name = $('Webhook: company in').first().json.body.name;
const site = String($('Fetch company site').first().json.data || '').replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<[^>]+>/g,' ').replace(/\s+/g,' ').slice(0,6000);
const news = ($('News search (Tavily)').first().json.results || []);
const seen = new Set(); const sources = [];
for (const r of news) { const host = new URL(r.url).hostname.replace(/^www\./,''); if (!seen.has(host)) { seen.add(host); sources.push({origin: host, tier: 'T3', url: r.url}); } }
const evidence = '[SOURCE company site]\n' + site + '\n\n' + news.map(r => '[SOURCE ' + r.url + ']\n' + (r.content||'').slice(0,1500)).join('\n\n');
return [{json: {name, evidence, sources}}];

const prev = $('Merge + build evidence').first().json;
const txt = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
const m = txt.match(/\{[\s\S]*\}/); if (!m) throw new Error('no JSON in model output');
const a = JSON.parse(m[0]);
for (const k of ['company','summary','signals','factors','conflicts','personas']) if (!(k in a)) throw new Error('missing ' + k);
const S = {funding_round:3, leadership_c_suite:3, expansion_plan:2, launch:2, use_of_funds_tech:2, valuation_up:1, ipo_filing:1, leadership_board:1, metric_claim:1, rebrand:0, secondary_sale:0};
const f = a.factors, tiers = prev.sources.map(s => s.tier);
let conf = .35 + (tiers.includes('T1') ? .25 : 0) + (prev.sources.length >= 2 ? .15 : 0) + (prev.sources.length >= 3 ? .10 : 0) - .07 * a.conflicts.filter(c => c.sev === 'open').length;
conf = Math.max(.2, Math.min(.95, +conf.toFixed(2)));
const raw = .35 * f.trigger * (0.4 + 0.6 * Math.pow(.5, 7/14)) + .30 * f.fit + .20 * f.budget + .15 * f.reach;
const final = +(raw * (.75 + .25 * conf)).toFixed(1);
const strength = Math.max(0, ...a.signals.map(s => S[s.kind] ?? 0));
const verdict = strength >= 2 && f.fit < 45 ? 'Low fit' : strength >= 2 && conf >= .6 ? 'Act' : strength >= 2 ? 'Verify first' : strength === 1 ? 'Watch' : 'Skip';
return [{json: {name: prev.name, analysis: JSON.stringify(a), sources: JSON.stringify(prev.sources), raw: +raw.toFixed(1), final, conf, verdict}}];
